/// <summary>
/// submitExceptions' answer. ErrorCode on failure: JOURNAL_POSTED, JOURNAL_NOT_FOUND,
/// CLAIM_LOST, INVALID_REQUEST, NOT_IMPLEMENTED.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountExceptionsResponse
{
    boolean success;
    str     errorCode;
    str     message;
    int     accepted;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('Accepted')]
public int parmAccepted(int _value = accepted)
{
    accepted = _value;
    return accepted;
}
